def main():
    os.makedirs(IMG_DIR, exist_ok=True)

    for data in PAGES:
        slug = data['slug']
        page_dir = os.path.join(PUBLIC_DIR, slug)
        os.makedirs(page_dir, exist_ok=True)

        # Generate HTML
        html = generate_page_html(data)
        html_path = os.path.join(page_dir, 'index.html')
        with open(html_path, 'w', encoding='utf-8') as f:
            f.write(html)

        # Generate SVG image
        svg = generate_svg(data)
        svg_path = os.path.join(IMG_DIR, f"{slug}.svg")
        with open(svg_path, 'w', encoding='utf-8') as f:
            f.write(svg)

        print(f"Created: {slug}/ ({data['keyword']})")

    print(f"\nTotal pages created: {len(PAGES)}")


if __name__ == '__main__':
    main()
